export default async function play(t) {
  await t.start();
  await t.waitFor(s => s.status === 'playing', 3000);
  let s = await t.state();
  t.expect(s.status === 'playing', 'Game should be playing after starting');

  const basketX = (st) => st.entities.find(e => e.type === 'player')?.x;

  // Movement
  let x0 = basketX(s);
  await t.press(['ArrowLeft'], 300);
  s = await t.state();
  const xL = basketX(s);
  t.expect(xL < x0, 'Pressing left should move the basket left');
  await t.press(['ArrowRight'], 400);
  s = await t.state();
  t.expect(basketX(s) > xL, 'Pressing right should move the basket right');
  await t.shot('moved');

  // Chase coins to score
  const end = Date.now() + 18000;
  let held = null;
  while (Date.now() < end) {
    s = await t.state();
    if (s.status !== 'playing' || s.score >= 2) break;
    const bx = basketX(s);
    const coins = s.entities.filter(e => e.type === 'coin').sort((a, b) => b.y - a.y);
    const target = coins.find(c => c.y < 280) || coins[0];
    let want = null;
    if (target) {
      if (target.x < bx - 8) want = 'ArrowLeft';
      else if (target.x > bx + 8) want = 'ArrowRight';
    }
    if (want !== held) {
      if (held) await t.up([held]);
      if (want) await t.down([want]);
      held = want;
    }
    await t.wait(30);
  }
  if (held) await t.up([held]);
  s = await t.state();
  t.expect(s.score >= 1, 'Catching a falling coin should increase the score');
  await t.shot('scored');

  // Lose by staying in a corner and missing coins
  await t.press(['ArrowLeft'], 1500);
  const over = await t.waitFor(st => st.status === 'gameover', 25000);
  t.expect(over, 'Missing three coins should end the game');
  s = await t.state();
  const finalScore = s.score;
  await t.shot('gameover');
  t.expect(finalScore >= 0 && Number.isFinite(finalScore), 'Game over should show a valid final score');

  // Restart with Space
  await t.press(['Space'], 100);
  const back = await t.waitFor(st => st.status === 'playing', 3000);
  t.expect(back, 'Pressing Space after game over should start a new round');
  s = await t.state();
  t.expect(s.score === 0, 'A new round should reset the score to 0');
  await t.shot('restarted');
}
