  await t.start();
  t.expect(await t.waitFor(s => s.status === 'playing', 3000), 'Game should be in playing status after starting');

  const paddleX = s => s.entities.find(e => e.type === 'paddle').x;
  const ballOf = s => s.entities.find(e => e.type === 'ball');
  const bricks = s => s.entities.filter(e => e.type === 'brick').length;

  // Controls: move paddle left then right
  let s0 = await t.state();
  const startBricks = bricks(s0);
  const x0 = paddleX(s0);
  await t.press('ArrowLeft', 300);
  const x1 = paddleX(await t.state());
  t.expect(x1 < x0, 'Pressing ArrowLeft should move the paddle left');
  await t.press('ArrowRight', 400);
  const x2 = paddleX(await t.state());
  t.expect(x2 > x1, 'Pressing ArrowRight should move the paddle right');
  await t.shot('playing');

  // Scoring: the ball should hit a brick, removing it and adding score
  const scored = await t.waitFor(s => s.score > 0, 8000);
  t.expect(scored, 'Hitting a brick with the ball should increase the score');
  if (scored) {
    const s = await t.state();
    t.expect(bricks(s) < startBricks || s.score > 0, 'A brick should disappear when the ball hits it');
    await t.shot('scored');
  }

  // Lose: keep the paddle away from the ball until it falls
  let over = false;
  const end = Date.now() + 25000;
  while (Date.now() < end) {
    const s = await t.state();
    if (s.status === 'gameover') { over = true; break; }
    const b = ballOf(s);
    const p = paddleX(s);
    await t.up(['ArrowLeft', 'ArrowRight']);
    if (b.x >= p) await t.down('ArrowLeft'); else await t.down('ArrowRight');
    await t.wait(60);
  }
  await t.up(['ArrowLeft', 'ArrowRight']);
  t.expect(over, 'Letting the ball fall past the paddle should end the game');
  await t.shot('gameover');

  // Restart with Space
  const before = await t.state();
  await t.press('Space', 100);
  const restarted = await t.waitFor(s => s.status === 'playing' && s.score === 0, 3000);
  t.expect(restarted, 'Pressing Space after game over should start a new round with score reset');
  const after = await t.state();
  t.expect(bricks(after) >= startBricks - 1 || before.status !== 'gameover', 'A new round should have the bricks restored');
}
