  const sc = await t.state();
  await t.wait(1200);
  const sc2 = await t.state();
  if (sc2.status === 'playing') t.expect(sc2.score > sc.score, '存活时间越长得分越高');

  // steer into a meteor to lose
  const deadline = Date.now() + 28000;
  let over = false;
  while (Date.now() < deadline) {
    const s = await t.state();
    if (s.status === 'gameover') { over = true; break; }
    const ship = s.entities.find(e => e.type === 'player');
    const rocks = s.entities.filter(e => e.type === 'meteor' && e.y < ship.y);
    if (rocks.length) {
      rocks.sort((a, b) => b.y - a.y);
      const r = rocks[0];
      const dx = r.x - ship.x;
      if (Math.abs(dx) > 6) await t.press(dx > 0 ? 'ArrowRight' : 'ArrowLeft', Math.min(120, Math.abs(dx) * 3));
      else await t.wait(30);
    } else {
      await t.wait(50);
    }
  }
  t.expect(over, '撞到陨石后游戏结束');
  const over_s = await t.state();
